// BPMN: "Actualizar estado de las alertas (abrir, mantener o cerrar)".
// Compara las alertas de hoy con las de la ejecución anterior (guardadas en el estado del flujo):
//   - alerta que aparece por primera vez  -> NUEVA (se abre)
//   - alerta que ya estaba abierta         -> PENDIENTE (se mantiene, con su antigüedad)
//   - alerta que ya no aparece             -> CERRADA (el stock volvió a estar sobre el mínimo, se repuso la vitrina o el lote ya no vence)
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const zona = { timeZone: 'America/Santiago' };
const hoy = new Date().toLocaleDateString('en-CA', zona);            // AAAA-MM-DD
const fechaCL = new Date().toLocaleDateString('es-CL', zona);
const dias = desde => Math.round((Date.parse(hoy) - Date.parse(desde)) / 86400000);
const plural = n => `${n} día${n === 1 ? '' : 's'}`;

const rows = $input.all().map(i => i.json).filter(r => r && r.tipo);   // sin filas = ninguna alerta hoy
const estado = $getWorkflowStaticData('global');
const previas = estado.alertas || {};
const claveDe = r => {
  const f = r.tipo === 'Vence' ? ((String(r.detalle).match(/vence el (\d{2}-\d{2})/) || [])[1] || '') : '';
  return [r.tipo, r.item, f].join('|');
};

const actuales = {};
const nuevas = [], pendientes = [], cerradas = [];
for (const r of rows) {
  const k = claveDe(r);
  const previa = previas[k];
  actuales[k] = { tipo: r.tipo, item: r.item, detalle: r.detalle, desde: previa ? previa.desde : hoy };
  (previa ? pendientes : nuevas).push({ ...actuales[k], dias: dias(actuales[k].desde) });
}
for (const [k, a] of Object.entries(previas)) {
  if (!actuales[k]) cerradas.push({ ...a, dias: dias(a.desde) });
}
estado.alertas = actuales;                                              // queda guardado para la ejecución de mañana

const abiertas = [...nuevas, ...pendientes];
const TITULOS = { Comprar: '🛒 Insumos para comprar', Vitrina: '🧁 Falta en vitrina', Vence: '⏰ Vence en 5 días o menos' };
let html = `<h2>Las 3 Delicias · alertas de inventario del ${fechaCL}</h2>`;
for (const tipo of ['Comprar', 'Vitrina', 'Vence']) {
  const items = abiertas.filter(a => a.tipo === tipo);
  if (!items.length) continue;
  html += `<h3>${TITULOS[tipo]} (${items.length})</h3><ul>` + items.map(a =>
    `<li><b>${esc(a.item)}</b>: ${esc(a.detalle)} <i>${a.dias > 0 ? `(pendiente hace ${plural(a.dias)})` : '(nueva)'}</i></li>`).join('') + '</ul>';
}
if (cerradas.length) {
  html += `<h3>✅ Cerradas desde ayer (${cerradas.length})</h3><ul>` + cerradas.map(a =>
    `<li>${esc(a.item)} <i>(${esc(a.tipo.toLowerCase())}; estuvo abierta ${plural(a.dias)})</i></li>`).join('') + '</ul>';
}
return [{ json: {
  asunto: `Inventario ${fechaCL}: ${abiertas.length} alertas abiertas (${nuevas.length} nuevas, ${pendientes.length} pendientes, ${cerradas.length} cerradas)`,
  html, total_abiertas: abiertas.length, nuevas: nuevas.length, pendientes: pendientes.length, cerradas: cerradas.length
} }];
